)

type S struct {
	A int32
	B int64
}

func main() {
	s := S{A: 1, B: 42}
	base := unsafe.Pointer(&s)
	// All arithmetic in one expression so the GC can't invalidate it:
	bp := unsafe.Pointer(uintptr(base) + unsafe.Offsetof(s.B))
	fmt.Println(*(*int64)(bp)) // read B through the computed pointer
}

