func fieldB(s *S) int64 {
	// pointer -> uintptr -> add -> back to unsafe.Pointer, all at once:
	p := unsafe.Pointer(uintptr(unsafe.Pointer(s)) + unsafe.Offsetof(s.B))
	return *(*int64)(p)
}

func ReadUint32LE(b []byte) uint32 {
	if len(b) < 4 {
		panic("need at least 4 bytes")
	}
	// Reinterpret the first 4 bytes as a uint32.
	// NOTE: correct ONLY on little-endian hardware. Prefer
	// encoding/binary.LittleEndian.Uint32 for portability.
	return *(*uint32)(unsafe.Pointer(&b[0]))
}
